<?php require_once '../config.php'; login_required('admin'); $rows=mysqli_query($conn,"SELECT i.*,b.title,u.name FROM issues i JOIN books b ON i.book_id=b.id JOIN users u ON i.user_id=u.id WHERE i.fine>0 ORDER BY i.id DESC");?><!doctype html><html><head><title>Fine</title><link rel="stylesheet" href="../assets/css/admin/fine.css"><link rel="stylesheet" href="../assets/css/admin/sidebar.css"></head><body><div class="layout"><?php include 'sidebar.php';?><main class="main"><h1>Fine Report</h1><div class="panel"><table><tr><th>Book</th><th>User</th><th>Fine</th><th>Status</th></tr><?php while($r=mysqli_fetch_assoc($rows)):?><tr><td><?=e($r['title'])?></td><td><?=e($r['name'])?></td><td>₹<?=$r['fine']?></td><td><?=$r['status']?></td></tr><?php endwhile;?></table></div></main></div></body></html>
